theorem toRees_bijective (hS : IsCompletelyZeroSimple S) {e : S}
    (he : IsPrimitiveIdempotent e) :
    Function.Bijective (toRees hS he)

theorem reesMatrix_isPrimitiveIdempotent {i : I} {l : Λ} {p : G}
    (hp : P l i = some p) :
    IsPrimitiveIdempotent (elem i p⁻¹ l : ReesMatrix G I Λ P)

theorem IsPrimitiveIdempotent.isGreenH_of_corner (hS : IsZeroSimple S) {e : S}
    (he : IsPrimitiveIdempotent e) {a : S} (ha : a ≠ 0)
    (hea : e * a = a) (hae : a * e = a) : a 𝓗 e

theorem IsSimplePrimitiveIdempotent.isPrimitiveIdempotent_withZero {e : S}
    (he : IsSimplePrimitiveIdempotent e) :
    IsPrimitiveIdempotent (e : WithZero S)

theorem sandwichMatrix_eq_some (hS : IsCompletelyZeroSimple S₀) {e : S₀}
    (he : IsPrimitiveIdempotent e) (l : ReesLIndex e) (i : ReesRIndex e) :
    sandwichMatrix e l i = some (simpleSandwich hS he l i)

theorem IsZeroMinimalRightIdeal.image_mul_left {R : Set S}
    (hR : IsZeroMinimalRightIdeal R) (a : S) :
    (a * ·) '' R = {0} ∨ IsZeroMinimalRightIdeal ((a * ·) '' R)

theorem IsZeroMinimalLeftIdeal.image_mul_right {L : Set S}
    (hL : IsZeroMinimalLeftIdeal L) (a : S) :
    (· * a) '' L = {0} ∨ IsZeroMinimalLeftIdeal ((· * a) '' L)
